    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Al despertar", "Alabado sea Allah, que nos dio la vida después de habernos dado la muerte (el sueño), y hacia Él es el retorno.", "Se dice justo al despertar, en agradecimiento a Allah.", "El Profeta ﷺ recitaba esta súplica al despertar — comenzar el día con gratitud y el recuerdo del más allá."),
        "dua_leaving_home" to DuaText("Al salir de casa", "En el nombre de Allah, confío en Allah; no hay poder ni fuerza sino en Allah.", "Se dice al salir de casa pidiendo la protección de Allah.", "Se le dice entonces al siervo: has sido guiado, protegido y amparado, y el diablo se aleja de él."),
